import React from 'react';
import { EnvConfig } from '@/constants/EnvConfig';

interface PageMetaProps {
    /** Page-specific title. Rendered as-is; callers add any " | Site Name" suffix themselves. */
    title: string;
    description: string;
    /** Path the canonical/`og:url` should point at, e.g. `/events/sangam-2026`. */
    path?: string;
    /** `article` for a specific dated item (an event); `website` for everything else. */
    type?: 'website' | 'article';
    image?: string;
    /** Serialised into an `application/ld+json` block for rich results. */
    structuredData?: Record<string, unknown>;
    /** Keeps thin or transient pages (a missing event, say) out of search results. */
    noIndex?: boolean;
    /**
     * Highest priority wins when several instances are mounted. The root route renders the
     * site-wide fallback at the default 0; a page describing its own subject passes a higher
     * value. Priority is explicit because React runs child effects *before* parent ones, so
     * mount order alone would let the generic root tags overwrite the specific page tags.
     */
    priority?: number;
}

interface ResolvedMeta {
    title: string;
    description: string;
    path?: string;
    type: 'website' | 'article';
    image: string;
    noIndex: boolean;
    structuredData?: Record<string, unknown>;
}

/** Absolute URL for `canonical`/`og:` tags, which are specified to reject relative paths. */
const absoluteUrl = (path?: string): string | undefined => {
    if (typeof window === 'undefined') return undefined;
    try {
        return path ? new URL(path, window.location.origin).toString() : window.location.href;
    } catch {
        return undefined;
    }
};

const LD_JSON_ID = 'page-meta-ld-json';

/** Updates an existing tag in place, or creates one, so a key can never be duplicated. */
const upsertTag = (selector: string, create: () => HTMLElement, apply: (el: HTMLElement) => void) => {
    let el = document.head.querySelector<HTMLElement>(selector);
    if (!el) {
        el = create();
        document.head.appendChild(el);
    }
    apply(el);
};

const upsertMeta = (attr: 'name' | 'property', key: string, content: string) => {
    upsertTag(
        `meta[${attr}="${key}"]`,
        () => {
            const el = document.createElement('meta');
            el.setAttribute(attr, key);
            return el;
        },
        (el) => el.setAttribute('content', content),
    );
};

const removeTag = (selector: string) => document.head.querySelector(selector)?.remove();

/**
 * Applies one page's metadata to `<head>`.
 *
 * Tags are written directly rather than through a library: this app runs React 19, whose native
 * hoisting of `<title>`/`<meta>` bypasses react-helmet-async's reconciliation, so Helmet emitted
 * duplicate description/og tags (one per mounted instance, plus the static ones in index.html)
 * and silently dropped `<script type="application/ld+json">`. Upserting by selector keeps exactly
 * one tag per key and updates the index.html defaults in place, so the no-JS fallback those tags
 * provide for link-preview bots stays accurate.
 */
const applyMeta = (meta: ResolvedMeta) => {
    const url = absoluteUrl(meta.path);
    const imageUrl = absoluteUrl(meta.image);

    document.title = meta.title;
    upsertMeta('name', 'description', meta.description);

    if (meta.noIndex) upsertMeta('name', 'robots', 'noindex, follow');
    else removeTag('meta[name="robots"]');

    if (url) {
        upsertTag(
            'link[rel="canonical"]',
            () => {
                const el = document.createElement('link');
                el.setAttribute('rel', 'canonical');
                return el;
            },
            (el) => el.setAttribute('href', url),
        );
        upsertMeta('property', 'og:url', url);
    }

    upsertMeta('property', 'og:type', meta.type);
    upsertMeta('property', 'og:title', meta.title);
    upsertMeta('property', 'og:description', meta.description);
    upsertMeta('property', 'og:site_name', EnvConfig.SiteName);
    upsertMeta('name', 'twitter:card', 'summary_large_image');
    upsertMeta('name', 'twitter:title', meta.title);
    upsertMeta('name', 'twitter:description', meta.description);
    if (imageUrl) {
        upsertMeta('property', 'og:image', imageUrl);
        upsertMeta('name', 'twitter:image', imageUrl);
    }

    if (meta.structuredData) {
        upsertTag(
            `script#${LD_JSON_ID}`,
            () => {
                const el = document.createElement('script');
                el.id = LD_JSON_ID;
                el.setAttribute('type', 'application/ld+json');
                return el;
            },
            (el) => {
                el.textContent = JSON.stringify(meta.structuredData);
            },
        );
    } else {
        removeTag(`script#${LD_JSON_ID}`);
    }
};

// Mounted instances, keyed by a per-instance id. Module scope rather than context: the winner
// has to be recomputed whenever any instance mounts, updates or unmounts.
const registry = new Map<number, { priority: number; meta: ResolvedMeta }>();
let nextId = 0;

const applyWinner = () => {
    let winner: { priority: number; meta: ResolvedMeta } | undefined;
    for (const entry of registry.values()) {
        if (!winner || entry.priority >= winner.priority) winner = entry;
    }
    if (winner) applyMeta(winner.meta);
};

/**
 * Sets the document title, description and Open Graph / Twitter tags for the current page.
 *
 * Mount it from a page whose subject loads asynchronously only once the data has arrived, so a
 * crawler never records a placeholder title.
 */
export const PageMeta: React.FC<PageMetaProps> = ({
    title,
    description,
    path,
    type = 'website',
    image = EnvConfig.SiteLogo,
    structuredData,
    noIndex = false,
    priority = 0,
}) => {
    const idRef = React.useRef<number | undefined>(undefined);
    idRef.current ??= nextId++;

    // Serialised so the effect re-runs when the content changes but not on a new object identity.
    const structuredDataKey = structuredData ? JSON.stringify(structuredData) : '';

    React.useEffect(() => {
        const id = idRef.current!;
        registry.set(id, {
            priority,
            meta: {
                title,
                description,
                path,
                type,
                image,
                noIndex,
                structuredData: structuredDataKey ? JSON.parse(structuredDataKey) : undefined,
            },
        });
        applyWinner();
        return () => {
            registry.delete(id);
            applyWinner();
        };
    }, [title, description, path, type, image, noIndex, structuredDataKey, priority]);

    return null;
};
